const body = $json.body || $json;

const phone = String(
  body.lead?.phone ||
  body.lead?.external_id ||
  body.lead_id ||
  ""
).trim();

if (!phone) {
  throw new Error("QA payload missing lead.phone");
}

const text = String(body.text || "").trim();

if (!text) {
  throw new Error("QA payload missing text");
}

const now = new Date().toISOString();

return [
  {
    json: {
      event: {
        channel: body.channel || "whatsapp",
        message_id: body.message_id || `qa_${Date.now()}`,
        timestamp: body.timestamp || now,
        text,
        message_type: body.message_type || "text",
        attachments: Array.isArray(body.attachments) ? body.attachments : [],
        source_metadata: {
          ...(body.source_metadata || {}),
          test_mode: true,
          raw_type: "qa_normalized"
        }
      },
      lead: {
        name: body.lead?.name || "Cliente QA",
        phone,
        external_id: phone,
        channel: body.lead?.channel || body.channel || "whatsapp"
      }
    }
  }
];

const normalized = $("normalize_qa_payload").item.json;
const db = $json;

const phone = String(
  normalized.lead?.phone ||
  normalized.lead?.external_id ||
  ""
).trim();

const body = $json.body || {};
const event = normalized.event || {};
const sourceMetadata = event.source_metadata || {};

return [
  {
    json: {
      channel: normalized.event.channel || "whatsapp",
      lead_id: phone,
      message_id: normalized.event.message_id,
      timestamp: normalized.event.timestamp,
      text: normalized.event.text,
      message_type: normalized.event.message_type || "text",
      attachments: normalized.event.attachments || [],
      contact: {
        wa_id: phone,
        name: normalized.lead?.name || "Cliente QA"
      },
      source_metadata: {
        ...sourceMetadata,
        test_mode: true,
        raw_type: "qa_normalized",
        qa_router: true,
        qa_db_lead_id: db.lead_id,
        qa_message_db_id: db.message_db_id
      },
      routing: body.routing || null,
      organization: body.organization || null,
      agent: body.agent || null,
      channel_config: body.channel_config || null,
      whatsapp_number: body.whatsapp_number || null
    }
  }
];

const payload = $("build_commercial_payload").item.json;
const row = $json || {};

function asObject(value, fallback = null) {
  if (!value) return fallback;
  if (typeof value === "object" && !Array.isArray(value)) return value;
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : fallback;
    } catch {
      return fallback;
    }
  }
  return fallback;
}

function asBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  if (String(value).toLowerCase() === "true") return true;
  return false;
}

const shouldProcess = asBool(row.should_process);
const routing = asObject(row.routing, payload.routing || {}) || {};
const organization = asObject(row.organization, payload.organization || null);
const agent = asObject(row.agent, payload.agent || null);
const channelConfig = asObject(row.channel_config, payload.channel_config || null);

return [{
  json: {
    ...payload,
    organization,
    agent,
    channel_config: channelConfig,
    should_process: shouldProcess,
    not_processed_reason: shouldProcess ? null : (row.error_code || "agent_channel_not_found_or_inactive"),
    routing: {
      ...(payload.routing || {}),
      ...routing,
      organization_id: routing.organization_id || organization?.id || null,
      agent_id: routing.agent_id || agent?.id || null
    },
    source_metadata: {
      ...(payload.source_metadata || {}),
      agent_resolution: row.legacy_mode === true || String(row.legacy_mode).toLowerCase() === "true" ? "legacy" : "agent_channels",
      agent_resolution_error: row.error_code || null
    }
  }
}];

return [{
  json: {
    ok: true,
    processed: false,
    reason: $json.not_processed_reason || "agent_channel_not_found_or_inactive",
    source: "qa_whatsapp_normalized_router",
    message: "QA event not processed because no active agent channel was found."
  }
}];

